{"action": "replace_code", "code": "def solve(data):
    left, right = data['base']
    if left >= right:
        return []

    blocked = data['blocked']
    result = []
    current_start = left

    for a, b in blocked:
        if a >= b:
            continue

        # Интервал блокировки [a, b)
        # Если блокировка полностью внутри текущего свободного интервала
        if a >= current_start and b <= right:
            # Если блокировка не покрывает весь интервал, добавляем части
            if a > current_start:
                result.append([current_start, a])
            if b < right:
                result.append([b, right])
            current_start = right  # Сбрасываем, так как весь интервал обработан
        # Если блокировка начинается до начала текущего интервала
        elif a < current_start:
            # Блокировка перекрывает начало текущего интервала
            if b <= right:
                # Блокировка полностью внутри текущего интервала
                current_start = b
            else:
                # Блокировка выходит за пределы текущего интервала
                if b > right:
                    current_start = right
                else:
                    # Блокировка внутри, но мы уже перешли к следующему шагу
                    # На самом деле, если b > right, то блокировка перекрывает весь оставшийся интервал
                    current_start = right
        # Если блокировка полностью после текущего интервала
        elif a >= right:
            continue
        # Если блокировка начинается внутри, но заканчивается после конца текущего интервала
        elif a < right and b > right:
            if a > current_start:
                result.append([current_start, a])
            current_start = right

    # Если остались свободные участки после всех блокировок
    if current_start < right:
        result.append([current_start, right])

    return result"
